theorem assoc_comp_congr
    {C : Type u} [Category.{v} C] {W X Y Z : C}
    (f : W ⟶ X) {g : X ⟶ Y} {h : Y ⟶ Z} {l : X ⟶ Z}
    (e : g ≫ h = l) :
    (f ≫ g) ≫ h = f ≫ l

theorem projectiveHomMap_mem {X Y : C} {d n : ℤ} {f : X ⟶ Y}
    (hf : f ∈ G.component X Y d) {x : ∀ i, P i ⟶ X}
    (hx : x ∈ (G.projectiveHomGrading P X).component n) :
    projectiveHomMap (k := k) P f x ∈ (G.projectiveHomGrading P Y).component (n + d)

theorem projectiveMatrixAction_mem {X : C} {d n : ℤ}
    {a : ∀ i j, P i ⟶ P j} {x : ∀ i, P i ⟶ X}
    (ha : a ∈ (G.projectiveMatrixGrading P).component d)
    (hx : x ∈ (G.projectiveHomGrading P X).component n) :
    (fun i ↦ ∑ j, a i j ≫ x j) ∈ (G.projectiveHomGrading P X).component (d + n)

theorem Quiver.Path.length_cast_eq {a b a' b' : U}
    (p : Path a b) (ha : a = a') (hb : b = b') :
    (p.cast ha hb).length = p.length

theorem homPathLinearEquiv_symm_single {x y : Category k Q}
    (p : Quiver.Path (vertex y) (vertex x)) (r : k) :
    (homPathLinearEquiv x y).symm (Finsupp.single p r) = r • pathHom p

theorem comp_mem_lengthComponent {x y z : Category k Q} {i j : ℕ}
    {f : x ⟶ y} {g : y ⟶ z}
    (hf : f ∈ lengthComponent x y i)
    (hg : g ∈ lengthComponent y z j) :
    f ≫ g ∈ lengthComponent x z (i + j)

theorem comp_mem_lengthTail {x y z : Category k Q} {i j : ℕ}
    {f : x ⟶ y} {g : y ⟶ z}
    (hf : f ∈ lengthTail x y i)
    (hg : g ∈ lengthTail y z j) :
    f ≫ g ∈ lengthTail x z (i + j)

theorem lengthComponent_zero_eq_bot_of_vertex_ne {x y : Category k Q}
    (hxy : vertex y ≠ vertex x) :
    lengthComponent x y 0 = ⊥

theorem positivePathSubmodule_eq_top_of_vertex_ne {x y : Category k Q}
    (hxy : vertex y ≠ vertex x) :
    positivePathSubmodule x y = ⊤

theorem lengthOnePath_eq_toPath {x y : Q}
    (p : {p : Quiver.Path x y // p.length = 1}) :
    p.1 = (arrowOfLengthOne p).toPath

@[ext]
theorem Hom.ext {X Y : Obj k T} {f g : Hom k T X Y}
    (h : f.linear = g.linear) : f = g

theorem card_le_of_nonzeroNonisomorphismLengthAtMost {L : ℕ}
    {P : Obj k T → Prop}
    (support_admissible : ∀ j, P (supportLine k T j))
    (hLength : HasNonzeroNonisomorphismLengthAtMost (Obj k T) P L) :
    Fintype.card T ≤ L

theorem card_le_of_positiveGrading {L : ℕ}
    {P : Obj k T → Prop}
    (support_admissible : ∀ j, P (supportLine k T j))
    (G : PositiveGrading (Obj k T) P L) :
    Fintype.card T ≤ L

theorem card_le_of_schurPositiveGrading {L : ℕ}
    (G : PositiveGrading (Obj k T) (IsSchur k T) L) :
    Fintype.card T ≤ L

theorem lineHom_ne_zero {U V : Set T} {hU : IsUpperSet U}
    {hV : IsUpperSet V} (hUV : U ⊆ V) :
    lineHom k T (hU := hU) (hV := hV) hUV ≠ 0

theorem lineHom_not_isIso {U V : Set T} {hU : IsUpperSet U}
    {hV : IsUpperSet V} (hUV : U ⊂ V) :
    ¬ IsIso (lineHom k T (hU := hU) (hV := hV) hUV.1)

theorem card_add_one_le_of_consecutiveAntichainBlock
    {L q : ℕ}
    (G : PositiveGrading (Obj k T) (IsSchur k T) L)
    {hq : q + 2 < Fintype.card T}
    (D : ConsecutiveAntichainBlock (T := T) q hq) :
    Fintype.card T + 1 ≤ L

theorem four_le_of_three_schurPositiveGrading {L : ℕ}
    (G : PositiveGrading (Obj k (Three k)) (IsSchur k (Three k)) L) :
    4 ≤ L

theorem antichainBlockIndex_le_of_rel {a b c x y : T}
    (hxy : antichainBlockRel a b c x y) :
    antichainBlockIndex a b c x ≤ antichainBlockIndex a b c y

theorem antichainBlockIndex_lt_of_rel {a b c x y : T}
    (hxy : antichainBlockRel a b c x y) (hne : x ≠ y) :
    antichainBlockIndex a b c x < antichainBlockIndex a b c y

theorem antichainBlockRank_anti {a b c x y : T}
    (H : IsThreeAntichain a b c) (hxy : y ≤ x) :
    antichainBlockRank a b c x ≤ antichainBlockRank a b c y

theorem antichainBlockRel_of_ge {a b c x y : T}
    (H : IsThreeAntichain a b c) (hxy : y ≤ x) :
    antichainBlockRel a b c x y

theorem finrank_triangularEndSpan {V : Type u}
    [AddCommGroup V] [Module k V] {n : ℕ}
    (b : Basis (Fin n) k V) :
    Module.finrank k (triangularEndSpan b) =
      Fintype.card (TriangularIndex n)

theorem linearIndependent_triangularEnd {V : Type u}
    [AddCommGroup V] [Module k V] {n : ℕ}
    (b : Basis (Fin n) k V) :
    LinearIndependent k (triangularEnd b)

theorem triangularEnd_preserves_flag {V : Type u}
    [AddCommGroup V] [Module k V] {n : ℕ}
    (b : Basis (Fin n) k V) (p : TriangularIndex n)
    (m : Fin (n + 1)) {x : V} (hx : x ∈ b.flag m) :
    triangularEnd b p x ∈ b.flag m

theorem comparable_of_trace_fst_eq (F : TwoSuccessor T) {x y : T}
    (hfst : (F.trace x).1 = (F.trace y).1) :
    x ≤ y ∨ y ≤ x

theorem eq_of_trace_eq {S : Type u} [PartialOrder S] [Fintype S]
    (F : TwoSuccessor S) {x y : S}
    (htrace : F.trace x = F.trace y) : x = y

theorem card_add_one_le_of_selectableSchurDetour
    (R : ReverseEnumeration T) {L q : ℕ}
    (G : PositiveGrading (Obj k T) (IsSchur k T) L)
    {hq : q + 2 < Fintype.card T}
    (D : SelectableSchurDetour k T R q hq) :
    Fintype.card T + 1 ≤ L

theorem boundary_card_eq (P I : V → Prop) [DecidablePred P] [DecidablePred I]
    (e : {x // ¬ P x} ≃ {x // ¬ I x}) :
    Fintype.card {x // P x} = Fintype.card {x // I x}

theorem boundaryDiagramMap_homOfBoundaryDiagramMap {X Y : Obj k T}
    (α : boundaryDiagram k T X ⟶ boundaryDiagram k T Y) :
    boundaryDiagramMap k T (homOfBoundaryDiagramMap k T α) = α

theorem IsSubdiagramOf.trans {N L M : BoundarySubdiagram k T F}
    (hNL : N.IsSubdiagramOf L) (hLM : L.IsSubdiagramOf M) :
    N.IsSubdiagramOf M

@[ext]
theorem ext {N L : BoundarySubdiagram k T F}
    (h : ∀ q, N.obj q = L.obj q) : N = L

theorem lineIso_hom_ne_zero
    {U V : Set T} {hU : IsUpperSet U} {hV : IsUpperSet V}
    (e : line k T U hU ≅ line k T V hV) : e.hom ≠ 0

theorem line_support_eq_of_iso
    {U V : Set T} {hU : IsUpperSet U} {hV : IsUpperSet V}
    (e : line k T U hU ≅ line k T V hV) : U = V

theorem line_support_subset_of_nonzero
    {U V : Set T} {hU : IsUpperSet U} {hV : IsUpperSet V}
    (f : line k T U hU ⟶ line k T V hV) (hf : f ≠ 0) : U ⊆ V

theorem block_gap (r h : ℕ) {i j : ℕ} {x y : ℤ}
    (hij : i < j) (hx : InBlock r h i x) (hy : InBlock r h j y) :
    (h : ℤ) < y - x

theorem block_index_eq_of_close (r h : ℕ) {i j : ℕ} {x y : ℤ}
    (hx : InBlock r h i x) (hy : InBlock r h j y)
    (hclose : |y - x| ≤ h) : i = j

theorem inBlock_of_between (r h j : ℕ) {x y z : ℤ}
    (hx : InBlock r h j x) (hy : InBlock r h j y)
    (hxz : x ≤ z) (hzy : z ≤ y) : InBlock r h j z

theorem coordinateProjection_of_mem_ne {d n : ℤ} {x : ∀ i, V i}
    (hx : x ∈ coordinateComponent (k := k) V degree d) (hdn : d ≠ n) :
    coordinateProjection (k := k) V degree n x = 0
